import { test, expect } from '@playwright/test';

test.describe('Element Manager - Add and Delete Elements', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/add_remove_elements/');
  });

  test('should add and delete elements successfully', async ({ page }) => {
    // Verify initial state
    const addButton = page.getByRole('button', { name: /add element/i });
    await expect(addButton).toBeVisible();
    const deleteButton = page.getByRole('button', { name: /delete element/i });
    await expect(deleteButton).toBeVisible();
    const listContainer = page.locator('[data-testid="element-list-container"]');
    await expect(listContainer).toBeVisible();

    // Add first element
    await addButton.click();
    const addedElement = page.locator('[data-testid="added-manually"]');
    await expect(addedElement).toHaveCount(1);
    const deleteBtn1 = page.getByRole('button', { name: /delete/i });
    await expect(deleteBtn1).toBeVisible();

    // Add second element
    await addButton.click();
    await expect(addedElement).toHaveCount(2);
    const deleteBtn2 = page.getByRole('button', { name: /delete/i });
    await expect(deleteBtn2).toBeVisible();

    // Delete first element
    await deleteBtn1.click();
    await expect(addedElement).toHaveCount(1);
    await expect(deleteBtn1).not.toBeVisible();
    await expect(deleteBtn2).toBeVisible();

    // Delete second element
    await deleteBtn2.click();
    await expect(addedElement).toHaveCount(0);
    await expect(deleteBtn2).not.toBeVisible();
  });

  test('should handle multiple additions and deletions correctly', async ({ page }) => {
    // Add three elements
    const addButton = page.getByRole('button', { name: /add element/i });
    await addButton.click();
    await addButton.click();
    await addButton.click();
    const addedElements = page.locator('[data-testid="added-manually"]');
    await expect(addedElements).toHaveCount(3);

    // Delete the middle element
    const deleteButtons = page.getByRole('button', { name: /delete/i });
    await deleteButtons.nth(1).click();
    await expect(addedElements).toHaveCount(2);
    await expect(deleteButtons).toHaveCount(2);

    // Delete the first element
    await deleteButtons.nth(0).click();
    await expect(addedElements).toHaveCount(1);
    await expect(deleteButtons).toHaveCount(1);

    // Delete the last element
    await deleteButtons.nth(0).click();
    await expect(addedElements).toHaveCount(0);
    await expect(deleteButtons).toHaveCount(0);

    // Verify list is empty
    const listContainer = page.locator('[data-testid="element-list-container"]');
    await expect(listContainer).toBeVisible();
    const emptyMessage = page.getByText(/no elements/i);
    await expect(emptyMessage).toBeVisible();
  });
});
